import {db} from "@/db";import {clients,externalEvents,leads,orders} from "@/db/schema";import {and,desc,eq} from "drizzle-orm";import {timingSafeEqual} from "node:crypto";
function authorized(request:Request){const expected=process.env.EXTERNAL_API_TOKEN||"",provided=request.headers.get("authorization")?.replace(/^Bearer\s+/i,"")||"";if(!expected||expected.length!==provided.length)return false;return timingSafeEqual(Buffer.from(expected),Buffer.from(provided))}
export async function GET(request:Request){if(!authorized(request))return Response.json({error:"unauthorized"},{status:401});const resource=new URL(request.url).searchParams.get("resource");if(resource==="orders"){const data=await db.select({id:orders.id,code:orders.code,stage:orders.stage,paymentStatus:orders.paymentStatus,deliveryStatus:orders.deliveryStatus,dueDate:orders.dueDate,total:orders.total,clientId:orders.clientId}).from(orders).orderBy(desc(orders.createdAt)).limit(100);return Response.json({data})}if(resource==="clients"){const data=await db.select({id:clients.id,name:clients.name,type:clients.type,email:clients.email,phone:clients.phone,mobile:clients.mobile,whatsapp:clients.whatsapp,status:clients.status}).from(clients).orderBy(desc(clients.createdAt)).limit(100);return Response.json({data})}return Response.json({error:"resource must be clients or orders"},{status:400})}
export async function POST(request:Request){if(!authorized(request))return Response.json({error:"unauthorized"},{status:401});const body=await request.json() as {source?:string;event?:string;externalId?:string;name?:string;phone?:string;email?:string;interest?:string;message?:string;payload?:Record<string,unknown>};if(!body.source||!body.event)return Response.json({error:"source and event are required"},{status:400});if(body.externalId){const [duplicate]=await db.select().from(externalEvents).where(and(eq(externalEvents.source,body.source),eq(externalEvents.externalId,body.externalId))).limit(1);if(duplicate)return Response.json({ok:true,deduplicated:true,eventId:duplicate.id})}const [event]=await db.insert(externalEvents).values({source:body.source,event:body.event,externalId:body.externalId,payload:body.payload||body}).returning();let leadId:number|undefined;if(body.event==="lead.created"&&body.name){const [lead]=await db.insert(leads).values({protocol:`PR-API-${Date.now().toString().slice(-7)}`,name:body.name,phone:body.phone,email:body.email,interest:body.interest,message:body.message,origin:"external_api",score:65,status:"novo"}).returning();leadId=lead.id}return Response.json({ok:true,eventId:event.id,leadId},{status:201})}
